-- hdmi_rx_xc7: Mimas A7 HDMI IN (DVI 1.0 sink) via Digilent dvi2rgb
-- (third_party/digilent-dvi2rgb, BSD-3; issue 0022). 27 MHz pixel clock
-- range (kClkRange 5: >= 25 MHz), no ILA debug cores; hot-plug detect
-- asserted. EDID (issue 0033) comes from our own ddc_edid on the 200 MHz
-- reference clock rather than dvi2rgb's file-initialised EEPROM_8b
-- (kEmulateDDC => false): the contents are a VHDL constant generated by
-- scripts/gen_edid.py, with no synthesis-time file path to resolve.
-- kHdmiAware (issue 0040): HDMI guard bands and data islands do not drive
-- DE (hdmi_rx_period); hdmi_seen / island_seen report them (pclk domain,
-- quasi-static).
-- PLL_BUFG (issue 0049, shield header receivers): PLLE2 + BUFG clocking
-- instead of MMCM + BUFIO/BUFR, so several receivers can share a clock
-- region; CLKIN_BUFG routes the TMDS clock to the PLL through a BUFG (PLL
-- in any region). INVERT(i) undoes a P/N swap of data lane i on the board.
--
-- Copyright (C) 2026 FPGA-DUT-Manager contributors. LGPL-2.1-or-later.
library ieee;
use ieee.std_logic_1164.all;

entity hdmi_rx_xc7 is
  generic (
    PLL_BUFG   : boolean := false;
    CLKIN_BUFG : boolean := true;
    INVERT     : std_logic_vector(2 downto 0) := "000"
  );
  port (
    -- pins
    tmds_clk_p, tmds_clk_n : in std_logic;
    tmds_p, tmds_n         : in std_logic_vector(2 downto 0);
    hpd                    : out std_logic;
    ddc_scl                : in    std_logic;   -- input only (no stretching)
    ddc_sda                : inout std_logic;   -- open drain
    -- 200 MHz IDELAYCTRL reference, reset while it is not stable
    ref_clk, ref_rst       : in std_logic;
    -- video out (pclk domain)
    pclk                   : out std_logic;
    rgb                    : out std_logic_vector(23 downto 0);  -- R & G & B
    de, hs, vs             : out std_logic;
    locked                 : out std_logic;
    hdmi_seen, island_seen : out std_logic
  );
end entity;

architecture rtl of hdmi_rx_xc7 is
  signal d : std_logic_vector(23 downto 0);
  signal sda_low : std_logic;
begin
  hpd <= '1';
  edid : entity work.ddc_edid
    generic map (CLK_HZ => 200_000_000)
    port map (clk => ref_clk, rst => ref_rst, scl => ddc_scl, sda => ddc_sda,
              sda_low => sda_low, reads => open);
  ddc_sda <= '0' when sda_low = '1' else 'Z';
  dvi : entity work.dvi2rgb
    generic map (kEmulateDDC => false, kRstActiveHigh => true,
                 kAddBUFG => not PLL_BUFG,   -- the PLL variant's pixel clock is on a BUFG already
                 kClkRange => 5, kDebug => false, kHdmiAware => true,
                 kPllBufg => PLL_BUFG, kClkInBufg => CLKIN_BUFG, kInvert => INVERT)
    port map (
      TMDS_Clk_p => tmds_clk_p, TMDS_Clk_n => tmds_clk_n,
      TMDS_Data_p => tmds_p, TMDS_Data_n => tmds_n,
      RefClk => ref_clk, aRst => ref_rst, aRst_n => not ref_rst,
      vid_pData => d, vid_pVDE => de, vid_pHSync => hs, vid_pVSync => vs,
      vid_pHdmi => hdmi_seen, vid_pIsland => island_seen,
      PixelClk => pclk, SerialClk => open, aPixelClkLckd => open, pLocked => locked,
      SDA_I => '1', SDA_O => open, SDA_T => open,
      SCL_I => '1', SCL_O => open, SCL_T => open,
      pRst => '0', pRst_n => '1');
  -- dvi2rgb orders vid_pData as R(23:16), B(15:8), G(7:0) (DVI channel order)
  rgb <= d(23 downto 16) & d(7 downto 0) & d(15 downto 8);
end architecture;
